	float rotation = 0;
	if(meta == 15) rotation = 90F / 180F * (float) Math.PI;
	if(meta == 12) rotation = 180F / 180F * (float) Math.PI;
	if(meta == 14) rotation = 270F / 180F * (float) Math.PI;
