/** Exact original RenderBlocks.renderFaceYPos full-block UVs and winding. */
static void appendLavaSurface(BufferBuilder buffer, TextureAtlasSprite lava, float height) {
	for (int ox = -1; ox <= 1; ox++) {
		for (int oz = -1; oz <= 1; oz++) {
			double x = ox - 0.5D, z = oz - 0.5D;
			buffer.pos(x + 1, height, z + 1).tex(lava.getMaxU(), lava.getMaxV()).normal(0, 1, 0).endVertex();
			buffer.pos(x + 1, height, z).tex(lava.getMaxU(), lava.getMinV()).normal(0, 1, 0).endVertex();
			buffer.pos(x, height, z).tex(lava.getMinU(), lava.getMinV()).normal(0, 1, 0).endVertex();
			buffer.pos(x, height, z + 1).tex(lava.getMinU(), lava.getMaxV()).normal(0, 1, 0).endVertex();
		}
	}
}

